import {MfeInitFunctionConfig} from './mfe-init-function-config';

export type MfeInitFunction = (config: MfeInitFunctionConfig) => void | Promise<MfeInitFunctionResponse>;

export interface MfeInitFunctionResponse {
  //This callback is called when the mfe is unloaded.
  //Clean up any listeners that were added the init function here.
  //Call reactRoot.unmount() to completely clean up the react app (If React is being used).
  unloadMfe: () => void;

  //If this function is provided, the DynamicComponent will not destroy and re-initialize
  //the MFE. Instead it will simply call the function with the updated MfeInitFunctionConfig.
  updateMfeConfig?: (props: MfeInitFunctionConfig) => void;
}